def color(i, j):
    """Coloring function: C(i, j) = (i+j) mod 4 + 1"""
    return (i + j) % 4 + 1

def check_2x2(i, j):
    """Checks the constraint for the 2x2 square starting at (i, j)"""

    colors = [
        color(i, j),
        color(i + 1, j),
        color(i, j + 1),
        color(i + 1, j + 1)
    ]

    # Constraint: At least two cells must have the same color.
    # This is equivalent to checking if the number of unique colors is <= 3.
    unique_colors = set(colors)

    if len(unique_colors) <= 3:
        return True
    else:
        return False

# Lattice size N = 100. We check 2x2 blocks starting at i, j where 0 <= i, j <= N-2 (i.e., 0 to 98)
N = 100
success = True
failed_count = 0
test_loops = 0

# Test a small sample first (e.g., 5x5 grid) to verify the logic
N_test = 5
print(f"--- Testing small N={N_test} grid ---")
test_success = True
for i in range(N_test - 1):
    for j in range(N_test - 1):
        if not check_2x2(i, j):
            print(f"Failure found at (i={i}, j={j}): {check_2x2(i, j)}")
            test_success = False
            break
    if not test_success:
        break

if test_success:
    print("Small grid test passed. All 2x2 subgrids satisfy the constraint.")
else:
    print("Small grid test failed.")

# Full check for 100x100 grid
print("\n--- Starting full 100x100 grid verification ---")
for i in range(N - 1):
    for j in range(N - 1):
        test_loops += 1
        if not check_2x2(i, j):
            success = False
            failed_count += 1
            print(f"CRITICAL FAILURE found at top-left corner (i={i}, j={j}).")
            # Since we expect success based on the pattern analysis, we break early on failure
            break 
    if not success:
        break

if success:
    print(f"\nSUCCESS: All {test_loops} subgrids in the 100x100 lattice satisfy the constraint.")
else:
    print(f"\nFAILURE: Found {failed_count} subgrids that violate the constraint.")
